changeSet.sql:
UPDATE agent_run r SET hold_reason = j.hold_reason
  FROM review_job j
 WHERE j.run_id = r.id AND j.workspace_id = r.workspace_id AND r.state = 'QUEUED'
   AND j.hold_reason IN ('BUDGET', 'SANDBOX_ROOM');
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_hold_reason
    CHECK (hold_reason IS NULL OR hold_reason IN ('BUDGET', 'SANDBOX_ROOM'));
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_hold_queued
    CHECK (hold_reason IS NULL OR state = 'QUEUED');
